/* @autogenerated */
package net.civeira.phylax.feature.observe.metric;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class EdgeDeriverUnitTest {

  @Test
  @DisplayName("A CLIENT span with a SERVER child of another source is an edge between both")
  void betweenSources() {
    MetricDeriver deriver = new MetricDeriver(100);
    EdgeDeriver edges = new EdgeDeriver(deriver);
    edges.client("ui", "s1", 1_000, 40, false, null, "api.local", 0);
    edges.server("api", "s1");
    List<MetricPoint> open = deriver.open();
    Assertions.assertEquals(1, open.size());
    Assertions.assertEquals("ui", open.get(0).src());
    Assertions.assertEquals(EdgeDeriver.ARROW + "api", open.get(0).route());
    Assertions.assertEquals(MetricDeriver.CLIENT, open.get(0).method());
    Assertions.assertEquals(0, edges.pending());
  }

  @Test
  @DisplayName("Database calls are edges at once; unmatched calls go to their host after waiting")
  void externals() {
    MetricDeriver deriver = new MetricDeriver(100);
    EdgeDeriver edges = new EdgeDeriver(deriver);
    edges.client("api", "d1", 1_000, 3, false, "db:mariadb/shop", null, 0);
    edges.client("api", "h1", 1_000, 80, true, null, "payments.example", 0);
    edges.client("api", "x1", 1_000, 80, false, null, null, 0);
    edges.sweep(60_000);
    Assertions.assertEquals(1, deriver.open().size());
    edges.sweep(200_000);
    Assertions.assertEquals(2, deriver.open().size());
    Assertions.assertTrue(deriver.open().stream().anyMatch(
        p -> p.route().equals(EdgeDeriver.ARROW + "payments.example") && p.errors() == 1));
    Assertions.assertEquals(0, edges.pending());
  }
}
